window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-27101\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μητραγύρτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1522 na letra μ · nº geral 27101</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sacerdote de Cibele, o qual mendiga em nome da deusa. 〈μήτηρ, ἀγείρω〉</p></section></article>\n<article id=\"entry-dgp-27102\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μητραλοίας, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1523 na letra μ · nº geral 27102</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">matricida. 〈μήτηρ, ἀλοιάω〉</p></section></article>\n<article id=\"entry-dgp-27103\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μητρικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1524 na letra μ · nº geral 27103</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de mãe; materno. 〈μήτηρ〉</p></section></article>\n<article id=\"entry-dgp-27104\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μητρίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1525 na letra μ · nº geral 27104</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">a mãe pátria; terra natal. 〈μήτηρ〉</p></section></article>\n<article id=\"entry-dgp-27105\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μητρόθε</h1><div class=\"entry-meta\"><span>DGP · ordem 1526 na letra μ · nº geral 27105</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e μητρόθεν adv. 1 da mãe; de parte da mãe 2 do seio da mãe. 〈μήτηρ, -θεν〉</p></section></article>\n<article id=\"entry-dgp-27106\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μητροκτονέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1527 na letra μ · nº geral 27106</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">matar a mãe; cometer matricídio. 〈μη­τροκτόνος〉</p></section></article>\n<article id=\"entry-dgp-27107\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μητροκτονία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1528 na letra μ · nº geral 27107</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">matricídio. 〈μητροκτόνος〉</p></section></article>\n<article id=\"entry-dgp-27108\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μητροκτόνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1529 na letra μ · nº geral 27108</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 matricida 2 referente a matricídio. 〈μήτηρ, κτείνω〉</p></section></article>\n<article id=\"entry-dgp-27109\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μητρομήτωρ, ορος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1530 na letra μ · nº geral 27109</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">avó materna. 〈μήτηρ〉</p></section></article>\n<article id=\"entry-dgp-27110\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μητροπάτωρ, ορος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1531 na letra μ · nº geral 27110</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">avô materno. 〈μήτηρ, πατήρ〉</p></section></article>\n<article id=\"entry-dgp-27111\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μητρόπολις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1532 na letra μ · nº geral 27111</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cidade-mãe; metrópole 2 cidade principal ou capital 3 terra natal; mãe pátria 4 fonte; fundamento; base; princípio. 〈μήτηρ, πόλις〉</p></section></article>\n<article id=\"entry-dgp-27112\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μητροφόνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1533 na letra μ · nº geral 27112</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">matricida. 〈μήτηρ, πεφνεῖν〉</p></section></article>\n<article id=\"entry-dgp-27113\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μητροφόντης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1534 na letra μ · nº geral 27113</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">μητροφόνος.</p></section></article>\n<article id=\"entry-dgp-27114\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μητρυιά, ᾶς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1535 na letra μ · nº geral 27114</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">madrasta. 〈μήτηρ〉</p></section></article>\n<article id=\"entry-dgp-27115\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μητρυιώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 1536 na letra μ · nº geral 27115</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de madrasta. 〈μητρυιά, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-27116\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μητρώϊος</h1><div class=\"entry-meta\"><span>DGP · ordem 1537 na letra μ · nº geral 27116</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. e jôn. = μητρῷος.</p></section></article>\n<article id=\"entry-dgp-27117\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μητρῷος1, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1538 na letra μ · nº geral 27117</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de mãe; da mãe; materno 2 da mãe dos deuses, de Cibele ♦ τὸ μητρῷον 3 templo de Cibele, em Atenas ♦ τὰ μητρῷα 4 culto de Cibele. 〈μήτηρ〉</p></section></article>\n<article id=\"entry-dgp-27118\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μητρῷος2,</h1><div class=\"entry-meta\"><span>DGP · ordem 1539 na letra μ · nº geral 27118</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. μετρώϊος, η, ον Medic. da matriz; do útero. 〈μήτρα〉</p></section></article>\n<article id=\"entry-dgp-27119\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μήτρως, ωος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1540 na letra μ · nº geral 27119</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tio materno. 〈μήτηρ〉</p></section></article>\n<article id=\"entry-dgp-27120\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηχανάασθε</h1><div class=\"entry-meta\"><span>DGP · ordem 1541 na letra μ · nº geral 27120</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª pl. pres. ind. pas. ép. de μηχανάω.</p></section></article>\n<article id=\"entry-dgp-27121\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηχανάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1542 na letra μ · nº geral 27121</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 imaginar ou planejar com arte 2 maquinar; tramar ♦ méd. (fut. μηχανήσομαι, perf. μεμηχάνημαι) 3 fabricar com arte; combinar com destreza 4 fabricar; imaginar 5 maquinar; tramar algo, ac., contra alguém, dat. 6 conspirar contra alguém, ἐπί e dat. 7 produzir; causar; ocasionar: μηχ. γέλωτα xen. provocar o riso, μηχ. ὅπως fazer de modo que, ser causa de. 〈μηχανή〉</p></section></article>\n<article id=\"entry-dgp-27122\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηχανέομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1543 na letra μ · nº geral 27122</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. 3ª pl. ἐμηχανέοντο) jôn. = μηχανάομαι, méd. pas. de μηχανάω.</p></section></article>\n<article id=\"entry-dgp-27123\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηχανεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1544 na letra μ · nº geral 27123</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">μηχανάω.</p></section></article>\n<article id=\"entry-dgp-27124\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηχανεώμενοι</h1><div class=\"entry-meta\"><span>DGP · ordem 1545 na letra μ · nº geral 27124</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. pres. pas. jôn. masc. pl. de μηχανάω.</p></section></article>\n<article id=\"entry-dgp-27125\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηχανή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1546 na letra μ · nº geral 27125</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 máquina; invenção engenhosa; engenho 2 máquina de guerra 3 máquina de teatro: prov. ὥσπερ ἀπὸ μηχανῆς dem. como de uma máquina de teatro, i.e., de modo imprevisível ou repentino, como por encanto, μηχανὴν αἴρειν levantar a máquina, i.e., realizar um golpe de teatro 4 meio; expediente; truque; artifício: πάσῃ μηχανῇ por todos os meios, οὐδεμιᾷ μηχανῇ por meio nenhum, οὐδεμία μηχανή ἐστι ὅκως οὐ ou μὴ οὐ</p></section></article>\n<article id=\"entry-dgp-27126\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 1547⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 1547 na letra μ · nº geral 27126</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ou τὸ μή her. não há qualquer meio de não…, τίς ἔστι μηχανή; com inf. que jeito há de? 5 engano; artifício; maquinação 6 dom de invenção; talento; habilidade. μηχάνημα, ατος (τό) 1 invenção engenhosa 2 engenho; máquina; mecanismo 3 máquina de guerra 4 meio; expediente 5 engano; artifício; maquinação. 〈μηχανάω〉</p></section></article>\n<article id=\"entry-dgp-27127\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηχανικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1548 na letra μ · nº geral 27127</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 industrioso; hábil no trabalho, gen. 2 construído por arte mecânica; de máquina; mecânico ♦ ἡ μηχανική 3 arte de construir máquinas. 〈μηχανή〉</p></section></article>\n<article id=\"entry-dgp-27128\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηχανόεις, όεσσα, όεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1549 na letra μ · nº geral 27128</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">industrioso. 〈μηχανή〉</p></section></article>\n<article id=\"entry-dgp-27129\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηχανοίατο</h1><div class=\"entry-meta\"><span>DGP · ordem 1550 na letra μ · nº geral 27129</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. pres. pas. jôn. de μηχανάομαι.</p></section></article>\n<article id=\"entry-dgp-27130\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηχανοποιός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1551 na letra μ · nº geral 27130</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 quem fabrica máquinas de guerra; engenheiro 2 maquinista de teatro. 〈μηχανή, ποιέω〉</p></section></article>\n<article id=\"entry-dgp-27131\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηχανορραφέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1552 na letra μ · nº geral 27131</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tramar intrigas. 〈μηχανορράφος〉</p></section></article>\n<article id=\"entry-dgp-27132\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηχανορράφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1553 na letra μ · nº geral 27132</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que maquina; que trama intrigas; insidioso. 〈μηχανή, ῥάπτω〉</p></section></article>\n<article id=\"entry-dgp-27133\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηχανοφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1554 na letra μ · nº geral 27133</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que carrega ou transporta máquinas. 〈μηχανή, φέρω〉</p></section></article>\n<article id=\"entry-dgp-27134\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηχανόων</h1><div class=\"entry-meta\"><span>DGP · ordem 1555 na letra μ · nº geral 27134</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. pres. at. ép., μηχανόωνται 3ª pl. pres. ind. pas. ép., μηχανόωντο 3ª pl. impf. pas. ép., μηχανόῳτο 3ª sing. opt. pres. pas. ép., μηχανῴατο 3ª pl. opt. pres. pas. jôn., de μηχανάω.</p></section></article>\n<article id=\"entry-dgp-27135\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μῆχαρ</h1><div class=\"entry-meta\"><span>DGP · ordem 1556 na letra μ · nº geral 27135</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">indecl. (τό) meio; remédio; expediente.</p></section></article>\n<article id=\"entry-dgp-27136\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μῆχος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1557 na letra μ · nº geral 27136</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">meio; expediente; remédio contra algo, gen.</p></section></article>\n<article id=\"entry-dgp-27137\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μία</h1><div class=\"entry-meta\"><span>DGP · ordem 1558 na letra μ · nº geral 27137</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fem. de εἷς.</p></section></article>\n<article id=\"entry-dgp-27138\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1559 na letra μ · nº geral 27138</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. μιανῶ, aor. ἐμίηνα, át. ἐμίανα, perf. μεμίαγκα; pas. aor. ἐμιάνθην, perf. μεμίασμαι) at. e méd. 1 tingir 2 sujar; manchar (de sangue, de poeira) 3 contaminar; profanar.</p></section></article>\n<article id=\"entry-dgp-27139\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιανθῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1560 na letra μ · nº geral 27139</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">subj. aor. pas. de μιαίνω.</p></section></article>\n<article id=\"entry-dgp-27140\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιαιφονέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1561 na letra μ · nº geral 27140</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐμιαιφόνουν, aor. pas. ἐμιαιφονήθην) 1 ser manchado por um crime de morte 2 matar; assassinar. 〈μιαιφόνος〉</p></section></article>\n<article id=\"entry-dgp-27141\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιαιφονία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1562 na letra μ · nº geral 27141</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de manchar-se pelo crime de mor­te. 〈μιαιφόνος〉</p></section></article>\n<article id=\"entry-dgp-27142\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιαιφόνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1563 na letra μ · nº geral 27142</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">manchado pelo crime de morte; assassino. 〈μιαίνω, πεφνεῖν〉</p></section></article>\n<article id=\"entry-dgp-27143\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιαρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1564 na letra μ · nº geral 27143</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impureza; perversidade; atrocidade. 〈μιαρός〉</p></section></article>\n<article id=\"entry-dgp-27144\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιαρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1565 na letra μ · nº geral 27144</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 manchado de sangue 2 manchado por um crime de morte 3 impuro; ímpio 4 no diálogo, ὦ μιαρέ biltre; calhorda 5 repugnante; abominável.</p></section></article>\n<article id=\"entry-dgp-27145\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μίασμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1566 na letra μ · nº geral 27145</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 mácula proveniente de um assassínio 2 contaminação; contágio 3 pessoa maculada por um assassínio. 〈μιαίνω〉</p></section></article>\n<article id=\"entry-dgp-27146\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιασμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1567 na letra μ · nº geral 27146</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de sujar; emporcalhamento 2 profanação; contaminação. 〈μιαίνω〉</p></section></article>\n<article id=\"entry-dgp-27147\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιάστωρ, ορος (ὁ</h1><div class=\"entry-meta\"><span>DGP · ordem 1568 na letra μ · nº geral 27147</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ἡ) 1 quem contamina; gênio impuro e malfeitor 2 flagelo vingador. 〈μιαίνω〉</p></section></article>\n<article id=\"entry-dgp-27148\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιγάζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1569 na letra μ · nº geral 27148</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) = μίγνυμαι, cf. μίγνυμι.</p></section></article>\n<article id=\"entry-dgp-27149\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιγάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 1570 na letra μ · nº geral 27149</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 misturado; reunido confusamente 2 promíscuo; mundano. 〈μίγνυμι〉</p></section></article>\n<article id=\"entry-dgp-27150\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μίγδα</h1><div class=\"entry-meta\"><span>DGP · ordem 1571 na letra μ · nº geral 27150</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. confusamente; embaralhadamente.</p></section></article>\n<article id=\"entry-dgp-27151\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιγείς, εῖσα, έν</h1><div class=\"entry-meta\"><span>DGP · ordem 1572 na letra μ · nº geral 27151</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor.2 pas. de μίγνυμι.</p></section></article>\n<article id=\"entry-dgp-27152\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μίγεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1573 na letra μ · nº geral 27152</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. ind. aor.2 pas. ép., μιγέωσι 3ª pl. subj. aor.2 pas. ép., μιγήῃς 2ª sing. subj. aor.2 pas. jôn., de μίγνυμι.</p></section></article>\n<article id=\"entry-dgp-27153\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιγήμεναι</h1><div class=\"entry-meta\"><span>DGP · ordem 1574 na letra μ · nº geral 27153</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 pas. ép. de μίγνυμι.</p></section></article>\n<article id=\"entry-dgp-27154\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μῖγμα</h1><div class=\"entry-meta\"><span>DGP · ordem 1575 na letra μ · nº geral 27154</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e μίγμα, ατος (τό) mistura; mescla; composto. 〈μίγνυμι〉</p></section></article>\n<article id=\"entry-dgp-27155\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μίγνυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 1576 na letra μ · nº geral 27155</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. μίξω, át. μείξω, aor. ἔμιξα, át. ἔμειξα, perf. μέ­μιχα; pas. fut. μιχθήσομαι, fut.2 μιγήσομαι, aor.1 ἐμίχθην, aor.2 ἐμίγην, perf. μέμιγμαι, fut. ant. μεμίξομαι) 1 misturar; mesclar uma coisa e outra, ac., uma coisa, ac., com outra, dat. ou μετά e gen. 2 unir; juntar ♦ pas. 3 unir-se; juntar-se a, dat.: κάρη κονίῃσιν ἐμίχθη hom. sua cabeça se juntou com a poeira, i.e., ele foi jogado no pó, κλισίῃσι μιγῆναι hom. misturar-se nas tendas, i.e., invadir as tendas, σὺν κακοῖς μεμιγμένος sóf. em meio de desgraças, μιγῆναί τινι ἐν δαῒ hom. misturar-se com alguém em um combate, combater com alguém 4 misturar-se a; relacionar-se com, dat. 5 relacionar-se sexualmente com, dat.</p></section></article>\n<article id=\"entry-dgp-27156\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μίδας, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 1577 na letra μ · nº geral 27156</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e α (ὁ) Midas, rei da Frigia.</p></section></article>\n<article id=\"entry-dgp-27157\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μιθριδάτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1578 na letra μ · nº geral 27157</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Mitrídates, n. de vários reis do Ponto.</p></section></article>\n<article id=\"entry-dgp-27158\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μιθριδατικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1579 na letra μ · nº geral 27158</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Mitrídates. 〈Μιθριδάτης〉</p></section></article>\n<article id=\"entry-dgp-27159\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μικκός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1580 na letra μ · nº geral 27159</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. e beóc. = μικρός.</p></section></article>\n<article id=\"entry-dgp-27160\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μικραδικητής, οῦ</h1><div class=\"entry-meta\"><span>DGP · ordem 1581 na letra μ · nº geral 27160</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) que comete injustiças nas pequenas coisas. 〈μικρός, ἀδικέω〉</p></section></article>\n<article id=\"entry-dgp-27161\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μικραίτιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1582 na letra μ · nº geral 27161</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se aborrece por pouco; detalhista. 〈μικρός, αἰτία〉</p></section></article>\n<article id=\"entry-dgp-27162\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μικρέμπορος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1583 na letra μ · nº geral 27162</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pequeno comerciante.</p></section></article>\n<article id=\"entry-dgp-27163\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μικροθυμία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1584 na letra μ · nº geral 27163</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pequenez de alma; pusilanimidade. 〈μικρός, θυμός〉</p></section></article>\n<article id=\"entry-dgp-27164\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μικρολογέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1585 na letra μ · nº geral 27164</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ser minucioso, detalhista ♦ méd. 2 ser minucioso, detalhista; disputar por ninharia 3 trazer dificuldades para, inf.; chicanear 4 comportar-se mesquinhamente com alguém, περί ou πρός e ac. 〈μικρός, λόγος〉</p></section></article>\n<article id=\"entry-dgp-27165\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μικρολογητέον</h1><div class=\"entry-meta\"><span>DGP · ordem 1586 na letra μ · nº geral 27165</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de μικρολογέω.</p></section></article>\n<article id=\"entry-dgp-27166\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μικρολογία,</h1><div class=\"entry-meta\"><span>DGP · ordem 1587 na letra μ · nº geral 27166</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. σμικρολογία, ας (ἡ) 1 atenção dada às pequenas coisas; pequenez de alma 2 espírito de chicana 3 sovinice; avareza. 〈μικρολόγος〉</p></section></article>\n<article id=\"entry-dgp-27167\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μικρολόγος,</h1><div class=\"entry-meta\"><span>DGP · ordem 1588 na letra μ · nº geral 27167</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. σμικρολόγος, ος, ον 1 minucioso; detalhista 2 que disputa por ninharias; chicanista 3 mesquinho 4 avaro; sovina. 〈μικρός, λέγω〉</p></section></article>\n<article id=\"entry-dgp-27168\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μικρολόγως</h1><div class=\"entry-meta\"><span>DGP · ordem 1589 na letra μ · nº geral 27168</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. minuciosamente; detalhadamente.</p></section></article>\n<article id=\"entry-dgp-27169\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μικρόλυπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1590 na letra μ · nº geral 27169</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se aflige por pequenas coisas. 〈μικρός, λύπη〉</p></section></article>\n<article id=\"entry-dgp-27170\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μικροπολίτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1591 na letra μ · nº geral 27170</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cidadão ou habitante de uma pequena cidade.</p></section></article>\n<article id=\"entry-dgp-27171\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μικροπρέπεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1592 na letra μ · nº geral 27171</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pequenez de espírito; mesquinhez; espírito de disputa por ninharia. 〈μικροπρεπής〉</p></section></article>\n<article id=\"entry-dgp-27172\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιροπρεπής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1593 na letra μ · nº geral 27172</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de pequenez de espírito 2 mesquinho; econômico 3 grosseiro; vulgar. 〈μικρός, πρέπω〉</p></section></article>\n<article id=\"entry-dgp-27173\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μικρός,</h1><div class=\"entry-meta\"><span>DGP · ordem 1594 na letra μ · nº geral 27173</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. σμικρός, ά, όν (comp. μικρότερος, μείων, μειότερος ou ἐλάσσων; superl. μικρότατος, μεῖστος, μειότατος ou ἐλάχιστος) 1 pequeno; de estatura pequena ou de pequena dimensão: μ. λίθος hom. pedra pequena, μ. ἔην δέμας hom. era de pequena estatura, μικρὰ πόλις xen. cidade pequena 2 em pequena quantidade; pouco considerável; escasso: μικρὸν μέλιτος ar. um pouco de mel 3 de qualidade inferior; pouco importante; de pouco valor; banal: διὰ μικρὸν ἐπολεμήσατε tuc. fizestes guerra por motivos de pouca importância, μικρὸν φρονεῖν sóf. ter sentimentos pequenos, baixos, ἐν σμικρῷ ποιεῖσθαι sóf. fazer pouco caso de, ac. 4 de pouca duração; breve: εἰς σμικρὸν χρόνον plat., μικρὸν χρόνον dem., ἐν μικρῷ χρόνῳ pínd., ἐν μικρῷ em pouco tempo ♦ adv. 5 ac. μικρόν xen., μικρά plat. um pouco: σμικρόν τι plat. um pouco, κατὰ σμικρόν xen. em pequenos pedaços ou pouco a pouco, ἐπὶ σμικρόν um tanto ou menos que nada, εἰς μικρόν luc. por um pouco de tempo, παρὰ μικρόν pol. por pouco, παρὰ μικρὸν ποιεῖσθαι, ποιεῖν, ἡγεῖσθαι fazer pouco caso de, παρὰ μικρὸν ἐδέησα com inf. faltou pouco para que eu…, κατὰ μικρά xen. em pequenos bocados 6 gen. μικροῦ por pouco; quase: μικροῦ δεῖν com inf. ou só μικροῦ faltar pouco para, por pouco, quase, μικροῦ κἀκεῖνον ἐξετραχήλισε xen. por pouco não estrangulou também a ele 7 dat. μικρῷ e σμικρῷ pouco; um pouco, ger. com adv.: σμικρῷ πρόσθεν plat. um pouco antes.</p></section></article>\n<article id=\"entry-dgp-27174\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μικρόστομος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1595 na letra μ · nº geral 27174</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que tem a boca pequena 2 que tem embocadura pequena (vaso, lâmpada etc). 〈μικρός, στόμα〉</p></section></article>\n<article id=\"entry-dgp-27175\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μικρότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1596 na letra μ · nº geral 27175</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pequenez 2 condição baixa; mediocridade de categoria. 〈μικρός〉</p></section></article>\n<article id=\"entry-dgp-27176\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μικροφροσύνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1597 na letra μ · nº geral 27176</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pequenez ou sutileza de espírito. 〈μικρός, φρήν〉</p></section></article>\n<article id=\"entry-dgp-27177\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μικροψυχία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1598 na letra μ · nº geral 27177</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pequenez de alma; baixeza de sentimentos. 〈μικρόψυχος〉</p></section></article>\n<article id=\"entry-dgp-27178\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μικρόψυχος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1599 na letra μ · nº geral 27178</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de alma pequena; de sentimentos pouco elevados; mesquinho 2 pusilânime. 〈μικρός, ψυχή〉</p></section></article>\n<article id=\"entry-dgp-27179\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μικρῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1600 na letra μ · nº geral 27179</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 pouco 2 em pequenos pedaços.</p></section></article>\n<article id=\"entry-dgp-27180\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μίκτο</h1><div class=\"entry-meta\"><span>DGP · ordem 1601 na letra μ · nº geral 27180</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. aor. méd. poét. de μίγνυμι.</p></section></article>\n<article id=\"entry-dgp-27181\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μικτός, ή</h1><div class=\"entry-meta\"><span>DGP · ordem 1602 na letra μ · nº geral 27181</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ός, όν misturado; mesclado. 〈μίγνυμι〉</p></section></article>\n<article id=\"entry-dgp-27182\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μιλησιακός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1603 na letra μ · nº geral 27182</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Μιλήσιος.</p></section></article>\n<article id=\"entry-dgp-27183\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μιλήσιος, ος</h1><div class=\"entry-meta\"><span>DGP · ordem 1604 na letra μ · nº geral 27183</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e α, ον 1 de Mileto; milésio ♦ ἡ Μιλησία 2 o território de Mileto. 〈Μίλητος〉</p></section></article>\n<article id=\"entry-dgp-27184\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μίλητος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1605 na letra μ · nº geral 27184</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Mileto, cidade da Jônia.</p></section></article>\n<article id=\"entry-dgp-27185\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μίλιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1606 na letra μ · nº geral 27185</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">a milha romana, espaço de mil passos, equivalente a 8 estádios. [lat.]</p></section></article>\n<article id=\"entry-dgp-27186\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιλτηλιφής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1607 na letra μ · nº geral 27186</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pintado de vermelhão. 〈μίλτος, ἀλείφω〉</p></section></article>\n<article id=\"entry-dgp-27187\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μιλτιάδης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1608 na letra μ · nº geral 27187</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Milcíades, general ateniense. 〈μίλτος〉</p></section></article>\n<article id=\"entry-dgp-27188\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μίλτινος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1609 na letra μ · nº geral 27188</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de mínio; de vermelhão ♦ τὸ μίλτινον 2 vermelhão. 〈μίλτος〉</p></section></article>\n<article id=\"entry-dgp-27189\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιλτοπάρῃος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1610 na letra μ · nº geral 27189</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de bordas ou faces pintadas de vermelhão (navio) 2 de superfície vermelha. 〈μίλτος, παρειά〉</p></section></article>\n<article id=\"entry-dgp-27190\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μίλτος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1611 na letra μ · nº geral 27190</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mínio ou vermelhão.</p></section></article>\n<article id=\"entry-dgp-27191\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιλτόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1612 na letra μ · nº geral 27191</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 revestir de vermelhão ♦ méd. 2 pintar-se com o vermelhão. 〈μίλτος〉</p></section></article>\n<article id=\"entry-dgp-27192\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιλτώ, οῦ (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1613 na letra μ · nº geral 27192</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Milto, lit. pintada de vermelhão, epít. de Aspásia. 〈μίλτος〉</p></section></article>\n<article id=\"entry-dgp-27193\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιλτώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 1614 na letra μ · nº geral 27193</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">da natureza ou da cor do vermelhão. 〈μίλτος, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-27194\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μίλων, ωνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1615 na letra μ · nº geral 27194</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Milon, atleta famoso de Crotona.</p></section></article>\n<article id=\"entry-dgp-27195\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιμέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1616 na letra μ · nº geral 27195</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 imitar; reproduzir algo, ac. 2 imitar; comportar-se como alguém, ac. 3 imitar por meio de uma arte; representar 4 mimicar; imitar por uma pantomima.</p></section></article>\n<article id=\"entry-dgp-27196\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιμηλός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1617 na letra μ · nº geral 27196</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que imita; hábil no imitar 2 imitado; falsificado ♦ ἡ μιμηλά dór. 3 imagem. 〈μιμέομαι〉</p></section></article>\n<article id=\"entry-dgp-27197\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μίμησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1618 na letra μ · nº geral 27197</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 imitação 2 representação; imagem; retrato 3 mimese; representação teatral. 〈μιμέομαι〉</p></section></article>\n<article id=\"entry-dgp-27198\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιμητέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1619 na letra μ · nº geral 27198</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de μιμέομαι.</p></section></article>\n<article id=\"entry-dgp-27199\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιμητής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1620 na letra μ · nº geral 27199</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 quem imita; imitador 2 que representa caracteres; poeta ou ator 3 impostor; charlatão. 〈μιμέομαι〉</p></section></article>\n<article id=\"entry-dgp-27200\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιμητικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1621 na letra μ · nº geral 27200</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem talento para imitar; imitador. 〈μιμέομαι〉</p></section></article>\n";
